import { test, expect } from '@playwright/test';
import * as path from 'path';
import { recordCreated, stamp } from '../disputes/helpers';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

function ddmmyyyy(daysFromNow: number): string {
  const d = new Date(Date.now() + daysFromNow * 86_400_000);
  const p = (n: number) => String(n).padStart(2, '0');
  return `${p(d.getDate())}${p(d.getMonth() + 1)}${d.getFullYear()}`;
}

test.describe('עסקה חדשה — אישור יצירה וחזרה לרשימת העסקאות', () => {
  test('מעמוד נותן השירות: "חזרה" של הדפדפן ממסך העסקה החדשה — לרשימת העסקאות @android @data (#1846ecd8)', async ({ page }) => {
    const title = `QA-AUTO-1846 ספק דפדפן ${stamp()}`;

    // 1. כמו 2.1, שלבים 1–4
    await page.goto('/wallet');
    await page.getByTestId('tab-providers').click();
    await page.getByText('שירה כהן — שיפוצים וניקיון').click();
    await page.getByRole('button', { name: 'פתיחת עסקה בטוחה' }).click();
    await expect(page).toHaveURL(/\/deals\/new/);
    await expect(page.getByRole('button', { name: /שירה כהן — שיפוצים וניקיון/ })).toBeVisible();

    const tb = page.getByRole('textbox', { name: 'הקלד/י' });
    await tb.nth(0).fill(title);
    await page.getByRole('button', { name: /סוג העסקה/ }).click();
    await page.getByText('שיפוץ ובנייה', { exact: true }).last().click();
    await tb.nth(1).fill('QA-AUTO — עסקת בדיקה אוטומטית, לא אמיתית.');
    await tb.nth(2).fill('5');
    const dates = page.getByRole('textbox', { name: '00/00/0000' });
    await dates.nth(0).click();
    await dates.nth(0).pressSequentially(ddmmyyyy(2), { delay: 40 });
    await dates.nth(1).click();
    await dates.nth(1).pressSequentially(ddmmyyyy(9), { delay: 40 });
    await page.getByRole('button', { name: 'פתיחת עסקה בטוחה' }).last().click();

    await page.waitForURL(/\/deals\/[0-9a-f-]{36}$/);
    const dealId = new URL(page.url()).pathname.split('/deals/')[1];
    recordCreated({ dealId, title, note: '#1846ecd8' });
    await expect(page.getByText(title).first()).toBeVisible();
    await expect(page.getByTestId('deal-state-chip')).toContainText('ממתין לאישור');

    // 2. page.goBack()
    await page.goBack();
    await expect(page).toHaveURL(/\/deals$/);
    await expect(page.getByTestId(`deal-${dealId}`)).toBeVisible();
    await expect(page).not.toHaveURL(/\/providers\//);
    await expect(page).not.toHaveURL(/\/deals\/new/);
  });
});
